import PestaniasConfiguraciones from "../../../Componentes/PestaniasConfiguraciones/PestaniasConfiguraciones";
import { useState, useEffect } from 'react';
import Boton from '../../../Componentes/Boton/Boton';
import Modal from '../../../Componentes/Modal/Modal';
import PlantillaConfiguraciones from '../../../Componentes/PlantillaConfiguraciones/PlantillaConfiguraciones';
import editar from '../../../assets/editar.png';
import mas from '../../../assets/mas.png';
import NuevaSucursal from "../../../Componentes/Formularios/NuevaSucursal/NuevaSucursal";
import '../Proveedores/Proveedores.css';
import ModificarSucursal from "../../../Componentes/Formularios/ModificarSucursal/ModificarSucursal";
import { useValidarSesion } from "../../../hooks/useValidarSesion";

export default function Sucursales() {

    //Recupero informacion del usuario logueado
    const { usuario } = useValidarSesion(); // obtener el token desde Zustand

    //BOOLEANO PARA PREGUNTAR SI EL USUARIO TIENE PERMISO DE crear sucursal
    const permisoCrearSucursal = usuario?.permisos?.some(
        (permiso) => permiso.nombrePermiso === 'crear sucursal'
    ) ||
        usuario?.permisos_extra?.some(
            (permiso) => permiso.nombrePermiso === 'crear sucursal'
        );


    ////////OBTENER LISTA DE SUCURSALES
    const [sucursales, setSucursales] = useState([]);
    const obtenerDatos = () => {
    fetch(`${import.meta.env.VITE_API_BASE_URL}/api/sucursal`)
            .then(respuesta => respuesta.json())
            .then(datos => setSucursales(datos))
            .catch(e => console.log(e));
    }

    useEffect(() => {
        obtenerDatos();
    }, []);

    /////////MODAL NUEVA SUCURSAL

    const [modalNuevaSucursal, setModalNuevaSucursal] = useState(false);
    const manejaModalNuevaSucursal = () => {
        if (modalNuevaSucursal) {
            obtenerDatos();
        }
        setModalNuevaSucursal(!modalNuevaSucursal);
    };

    ////////MODAL MODIFICA SUCURSAL
    const [modalModificaSucursal, setModalModificaSucursal] = useState(false);
    const manejaModalModificaSucursal = () => {
        if (modalModificaSucursal) {
            obtenerDatos();
        }
        setModalModificaSucursal(!modalModificaSucursal);
    };

    //////MANEJA SELECCION
    const [seleccionado, setSeleccionado] = useState('');
    const manejaSeleccion = ({ id_sucursal, nombre, direccion, ciudad, provincia,foto,foto_url }) => {
        setSeleccionado({ id_sucursal, nombre, direccion, ciudad, provincia,foto,foto_url });
        manejaModalModificaSucursal();
    }
    console.log(seleccionado);

    /////////LAYOUT

    const navigation = <PestaniasConfiguraciones></PestaniasConfiguraciones>

    const main = <div className='__cuerpo_proveedores'>
        <div className='__cabecera_proveedores'>
            <h1>Sucursales</h1>
            {permisoCrearSucursal && <Boton icono={mas} habilitado onClick={manejaModalNuevaSucursal} title="Crear nueva sucursal"></Boton>}
        </div>
        <div className='__lista_proveedores'>
            {sucursales.map((item, index) => (
                <div className="__proveedor_item" key={index}>
                    {permisoCrearSucursal ? <span className='__proveedor_categoria'>{`${item.nombre} - ${item.direccion}, ${item.ciudad}, ${item.provincia}`}</span> :
                        <span className='__proveedor_categoria' style={{ padding: "10px" }}>{`${item.nombre} - ${item.direccion} - ${item.ciudad} - ${item.provincia}`}</span>}
                    {permisoCrearSucursal && <Boton icono={editar} habilitado onClick={() => manejaSeleccion({
                        id_sucursal: item.id_sucursal,
                        nombre: item.nombre,
                        direccion: item.direccion,
                        ciudad: item.ciudad,
                        provincia: item.provincia,
                        foto:item.foto,
                        foto_url:item.foto_url
                    })} title="Editar sucursal"></Boton>}
                </div>

            ))}

        </div>
        <Modal visible={modalNuevaSucursal} funcion={manejaModalNuevaSucursal} titulo="Nueva Sucursal" anchura="500px">
            <NuevaSucursal onGuardar={manejaModalNuevaSucursal}></NuevaSucursal>
        </Modal>
        <Modal visible={modalModificaSucursal} funcion={manejaModalModificaSucursal} titulo="Modificar Sucursal" anchura="500px" >
            <ModificarSucursal onGuardar={manejaModalModificaSucursal} autocompletar={seleccionado}></ModificarSucursal>
        </Modal>


    </div>


    return <PlantillaConfiguraciones navigation={navigation} main={main} />;
}