import { useForm } from "react-hook-form"
import Tarjeta from "../../ComponentesFormulario/Tarjeta/Tarjeta";
import Input from "../../Input/Input";
import Boton from "../../Boton/Boton";
import { toast } from "sonner";
import { useValidarSesion } from "../../../hooks/useValidarSesion";
import { useState } from "react";
import '../NuevaSucursal/NuevaSucursal.css';
import no_encontrado from "../../../assets/no_encontrado.png";

export default function ModificarSucursal({ onGuardar, autocompletar }) {
    const { token } = useValidarSesion();
    const [modificar, setModificar] = useState(false);
    const [cargando, setCargando] = useState(false);

    // Estados para manejo de imágenes
    const [imagenActual, setImagenActual] = useState(
    autocompletar.foto_url ? `${import.meta.env.VITE_API_BASE_URL}${autocompletar.foto_url}` : no_encontrado
    );
    const [nuevaImagen, setNuevaImagen] = useState(null);
    const [archivoImagen, setArchivoImagen] = useState(null);
    const [mostrarInputFile, setMostrarInputFile] = useState(false);
    const [imagenEliminada, setImagenEliminada] = useState(false);

    const manejaModificacion = () => setModificar(!modificar);

    const manejarCambioImagen = (e) => {
        const archivo = e.target.files[0];
        if (archivo) {
            setArchivoImagen(archivo);
            setImagenEliminada(false); // Si sube nueva imagen, no está eliminada
            const reader = new FileReader();
            reader.onloadend = () => {
                setNuevaImagen(reader.result);
            };
            reader.readAsDataURL(archivo);
        }
        setMostrarInputFile(false); // Ocultar input después de seleccionar
    };

    const activarCambioImagen = () => {
        setMostrarInputFile(true);
        setNuevaImagen(null);
        setArchivoImagen(null);
        setImagenEliminada(false);
    };

    const cancelarCambioImagen = () => {
        setNuevaImagen(null);
        setArchivoImagen(null);
        setMostrarInputFile(false);
        setImagenEliminada(false);
    };

    const eliminarImagenActual = () => {
        setImagenActual(no_encontrado);
        setNuevaImagen(null);
        setArchivoImagen(null);
        setImagenEliminada(true);
        setMostrarInputFile(false);
    };

    const { register, handleSubmit, formState: { errors }, reset } = useForm({
        defaultValues: {
            nombre: autocompletar.nombre,
            ciudad: autocompletar.ciudad,
            direccion: autocompletar.direccion,
            provincia: autocompletar.provincia
        }
    });

    const onSubmit = async (data) => {
        setCargando(true);

        const formData = new FormData();
        formData.append("nombre", data.nombre);
        formData.append("direccion", data.direccion);
        formData.append("ciudad", data.ciudad);
        formData.append("provincia", data.provincia);
        formData.append("_method", "PUT");

        // Manejo de imágenes
        if (archivoImagen) {
            formData.append("foto", archivoImagen);
        } else if (imagenEliminada) {
            // Si eliminó la imagen, enviamos un campo vacío o null
            // Depende de cómo lo maneje tu backend
            formData.append("eliminar_foto", "true");
        }

        try {
            const respuesta = await fetch(`${import.meta.env.VITE_API_BASE_URL}/api/sucursal/${autocompletar.id_sucursal}`, {
                method: 'POST',
                headers: {
                    'Accept': 'application/json',
                    'Authorization': `Bearer ${token}`
                },
                body: formData,
            });

            const dataRespuestaSucursal = await respuesta.json().catch(() => ({}));

            if (respuesta.ok) {
                toast.success("Sucursal Modificada correctamente.", { className: "__toaster_success" });
                setModificar(false); // Salir del modo modificar
                onGuardar();

                // Resetear estados de imagen
                if (dataRespuestaSucursal?.sucursal?.foto_url) {
                    setImagenActual(`${import.meta.env.VITE_API_BASE_URL}${dataRespuestaSucursal.sucursal.foto_url}`);
                }
                setNuevaImagen(null);
                setArchivoImagen(null);
                setMostrarInputFile(false);
                setImagenEliminada(false);
            } else {
                if (respuesta.status === 422 && dataRespuestaSucursal?.errors) {
                    const errores = Object.values(dataRespuestaSucursal.errors).flat().join('\n');
                    toast.error(errores, { className: "__toaster_error" });
                } else {
                    const mensajeError = dataRespuestaSucursal?.error || "Error al modificar Sucursal.";
                    toast.error(mensajeError, { className: "__toaster_error" });
                }
            }
        } catch (error) {
            console.error('Error en la solicitud:', error);
            toast.error("Error inesperado al modificar la sucursal.", { className: "__toaster_error" });
        } finally {
            setCargando(false);
        }
    };

    return (
        <form onSubmit={handleSubmit(onSubmit)} className="__formulario_nueva_sucursal">
            <div className="__cuerpo_nueva_sucursal">
                <div className="__columna1">
                    <Tarjeta descripcion="Nombre Sucursal" forid="nombre" mensajeError={errors.nombre?.message}>
                        <Input
                            tipo="text"
                            id="nombre"
                            deshabilitado={!modificar}
                            {...register("nombre", { required: { value: true, message: "Ingrese nombre de la sucursal" } })}
                        />
                    </Tarjeta>
                    <Tarjeta descripcion="Provincia" forid="provincia" mensajeError={errors.provincia?.message}>
                        <Input
                            tipo="text"
                            id="provincia"
                            deshabilitado={!modificar}
                            {...register("provincia", { required: { value: true, message: "Ingrese provincia" } })}
                        />
                    </Tarjeta>

                </div>

                <div className="__columna2">
                    <Tarjeta descripcion="Direccion" forid="direccion" mensajeError={errors.direccion?.message}>
                        <Input
                            tipo="text"
                            id="direccion"
                            deshabilitado={!modificar}
                            {...register("direccion", { required: { value: true, message: "Ingrese direccion" } })}
                        />
                    </Tarjeta>
                    <Tarjeta descripcion="Ciudad" forid="ciudad" mensajeError={errors.ciudad?.message}>
                        <Input
                            tipo="text"
                            id="ciudad"
                            deshabilitado={!modificar}
                            {...register("ciudad", { required: { value: true, message: "Ingrese ciudad" } })}
                        />
                    </Tarjeta>
                </div>
            </div>
            <div style={{margin:"3rem 3rem 2rem 3rem"}}>

                {/*SECCIÓN DE IMAGEN  */}
                <Tarjeta descripcion="Foto de la Sucursal">
                    <div className="__contenedor_imagen">
                        {nuevaImagen ? (
                            // Vista previa de nueva imagen seleccionada
                            <div className="__preview_imagen" style={{ display: 'flex', alignItems: 'flex-start', gap: '20px',flexDirection:"row" }}>
                                <img src={nuevaImagen} alt="Nueva preview" style={{ maxWidth: "200px" }} />
                                <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
                                    <Boton
                                        descripcion="Cancelar"
                                        onClick={cancelarCambioImagen}
                                        habilitado={modificar}
                                    />
                                </div>
                            </div>
                        ) : (
                            // Imagen actual o placeholder
                            <div className="__preview_imagen" style={{ display: 'flex', alignItems: 'flex-start', gap: '20px' }}>
                                <img
                                    src={imagenEliminada ? no_encontrado : imagenActual}
                                    alt="Sucursal"
                                    style={{ maxWidth: "200px" }}
                                />

                                <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
                                    <Boton
                                        descripcion="Cambiar"
                                        onClick={activarCambioImagen}
                                        habilitado={modificar && !mostrarInputFile}
                                    />
                                    <Boton
                                        descripcion="Eliminar"
                                        onClick={eliminarImagenActual}
                                        habilitado={modificar && !imagenEliminada && imagenActual !== no_encontrado && !mostrarInputFile}
                                    />
                                </div>
                            </div>
                        )}

                        {/* Input file solo cuando se hace clic en "Cambiar" */}
                        {modificar && mostrarInputFile && (
                            <div style={{ marginTop: "10px" }}>
                                <input
                                    type="file"
                                    accept="image/*"
                                    onChange={manejarCambioImagen}
                                />
                                <div style={{ marginTop: "10px" }}>
                                    <Boton
                                        descripcion="Cancelar"
                                        onClick={cancelarCambioImagen}
                                        habilitado
                                    />
                                </div>
                            </div>
                        )}
                    </div>
                </Tarjeta>
            </div>

            <div className="__boton_nueva_sucursal" style={{ justifyContent: 'space-around' }} >
                <Boton
                    descripcion={modificar ? 'Cancelar' : 'Modificar'}
                    onClick={manejaModificacion}
                    habilitado={!cargando}
                />
                {modificar && (
                    <Boton
                        descripcion={cargando ? 'Guardando...' : 'Guardar'}
                        habilitado={!cargando}
                        submit
                    />
                )}
            </div>
        </form>
    )
}